import * as THREE from 'three/webgpu';
import { texture, uv, uniform, vec4, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-thumb';

  const { x = 2.5, y = 1.6, z = 0 } = config.scenePosition || {};
  group.position.set(x, y, z);
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  group.rotation.set(rot.x, rot.y, rot.z);
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.scale.set(scl.x, scl.y, scl.z);

  const width = 1.4;
  const height = width * (320 / 512);
  const captionHeight = 0.22;

  const imageUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const geo = new THREE.PlaneGeometry(width, height);
  const hoverAmount = uniform(0);

  const mat = new THREE.MeshBasicNodeMaterial();
  const tex = texture(map, uv());
  mat.colorNode = mix(tex, vec4(1.0, 1.0, 1.0, 1.0), hoverAmount.mul(0.08));
  mat.transparent = true;

  const imagePlane = new THREE.Mesh(geo, mat);
  imagePlane.position.set(0, captionHeight * 0.5, 0);
  group.add(imagePlane);

  const captionGeo = new THREE.PlaneGeometry(width, captionHeight);
  const captionMat = new THREE.MeshBasicNodeMaterial();
  const inkColor = new THREE.Color('#16161d');
  captionMat.colorNode = vec4(inkColor.r, inkColor.g, inkColor.b, 0.92);
  captionMat.transparent = true;
  const captionStrip = new THREE.Mesh(captionGeo, captionMat);
  captionStrip.position.set(0, -height * 0.5, 0.001);
  group.add(captionStrip);

  const edgeGeo = new THREE.PlaneGeometry(width + 0.02, height + captionHeight + 0.02);
  const edgeMat = new THREE.MeshBasicNodeMaterial();
  const accentColor = new THREE.Color('#ff2a38');
  const focusOpacity = uniform(0);
  edgeMat.colorNode = vec4(accentColor.r, accentColor.g, accentColor.b, focusOpacity);
  edgeMat.transparent = true;
  const edgeFrame = new THREE.Mesh(edgeGeo, edgeMat);
  edgeFrame.position.set(0, 0, -0.001);
  group.add(edgeFrame);

  let captionLabel = null;
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    captionLabel = ctx.fontAtlas.createText({
      text: 'Journal',
      font: 'JetBrains Mono',
      weight: 400,
      size: 0.09,
      color: '#e8ecf2'
    });
    captionLabel.position.set(-width * 0.5 + 0.1, -height * 0.5 - captionHeight * 0.5, 0.01);
    group.add(captionLabel);
  }

  const baseY = group.position.y;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.35, ease: 'power3.out' }, 0);
  hoverTl.to(hoverAmount, { value: 1, duration: 0.35, ease: 'power3.out' }, 0);

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(group.scale, { x: scl.x * 0.97, y: scl.y * 0.97, z: scl.z * 0.97, duration: 0.12, ease: 'back.out' });

  const focusTl = gsap.timeline({ paused: true });
  focusTl.to(focusOpacity, { value: 0.6, duration: 0.2, ease: 'power2.out' });

  function onPointerOver() {
    hoverTl.play();
  }
  function onPointerOut() {
    hoverTl.reverse();
  }
  function onPointerDown() {
    pressTl.play(0);
  }
  function onPointerUp() {
    pressTl.reverse();
  }
  function onClick() {
    if (ctx.eventBus && typeof ctx.eventBus.emit === 'function') {
      ctx.eventBus.emit('hub-journal.select', { nodeId: 'hub-journal-card-thumb' });
    }
    if (group.userData.handlers && group.userData.handlers.onNavigate) {
      group.userData.handlers.onNavigate('hub-journal.select');
    }
  }
  function onFocus() {
    focusTl.play();
  }
  function onBlur() {
    focusTl.reverse();
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
    onFocus,
    onBlur
  };

  group.userData.cleanup = function cleanup() {
    hoverTl.kill();
    pressTl.kill();
    focusTl.kill();
    geo.dispose();
    captionGeo.dispose();
    edgeGeo.dispose();
    mat.dispose();
    captionMat.dispose();
    edgeMat.dispose();
    if (map && typeof map.dispose === 'function') map.dispose();
    if (captionLabel && captionLabel.userData && typeof captionLabel.userData.cleanup === 'function') {
      captionLabel.userData.cleanup();
    }
  };

  return group;
}
